  'runWhy.questionsOpen': { one: 'In {period} ist noch eine Frage zur MWST offen: die Abrechnung wird erst erzeugt, wenn sie beantwortet ist. Beantworte sie unter Aufgaben, dann «Weiter».', other: 'In {period} sind noch {n} Fragen zur MWST offen: die Abrechnung wird erst erzeugt, wenn sie beantwortet sind. Beantworte sie unter Aufgaben, dann «Weiter».' },
  'runWhy.figuresChanged': 'Die Bücher von {period} stimmen nicht mehr mit der eingereichten Abrechnung überein (Ziffern {boxes}): eingereicht CHF {filed}, heute laut Büchern CHF {now}. Die Abrechnung ist bei der ESTV eingereicht, die Periode bleibt gesperrt: nur Änderungen, die die Bücher zur Abrechnung zurückbringen, gehen durch. Stell die Buchungen so her, wie sie bei der Einreichung waren (Änderungen › «Rückgängig», oder von Hand), dann «Weiter».',
  'runWhy.filedNotSealed': '{period} ist bei der ESTV eingereicht, die Bücher weichen aber noch von der Abrechnung ab. Sie wird nicht neu erstellt: stell die Buchungen her, wie sie bei der Einreichung waren, dann «Weiter» beim Einreichungslauf.',
