  'onboarding.s.hello': 'Hallo {owner}. Ich richte deine Buchhaltung mit dir ein: Firma und MWST, ab wann gebucht wird, Bank, Belege und was die App über deine Geschäftspartner wissen soll. Jede Frage beantwortest du mit einem Klick oder in deinen Worten.',
  'onboarding.s.helloNoName': 'Hallo. Ich richte deine Buchhaltung mit dir ein: Firma und MWST, ab wann gebucht wird, Bank, Belege und was die App über deine Geschäftspartner wissen soll. Jede Frage beantwortest du mit einem Klick oder in deinen Worten.',
