  'onboarding.r.filedLater': 'Eingereicht: {periods}. Ein eingereichtes Quartal kommt erst in die Bücher, wenn es aus dem Journal deines bisherigen Programms nachgerechnet und Ziffer für Ziffer mit der Abrechnung verglichen ist; dann versiegelst du es, und es ändert sich nie mehr. Diesen Vergleich gibt es in der App noch nicht, er kommt mit dem Import aus dem bisherigen Programm. Abschliessen kannst du bis dahin von Hand.',
